// @name Now playing
// @background #000000
// @refresh 1
// A player: play and pause, skip back and forward, and drag the bar to seek.
// The cover is a gradient and an SVG; the bar moves with the clock while it
// plays, and follows the finger while it is held (a captured press).
// `at` (a field) pins the time, for a snapshot; empty, it is the clock.
// `ink` is a cover on colour e-paper (a Spectra's six inks): one solid ink,
// its disc in the black or white that reads on it.
const tracks = [
  { title: 'Log Cabin Lullaby', artist: 'The Forest Choir', length: 201, cover: 'from-fuchsia-500 to-indigo-800', bg: 'bg-fuchsia-950', ink: 'bg-[#ff0000] text-white' },
  { title: 'Northern Lights', artist: 'Aurora Static', length: 244, cover: 'from-emerald-300 to-cyan-800', bg: 'bg-emerald-950', ink: 'bg-[#00ff00] text-white' },
  { title: 'Paper Boats', artist: 'Juniper Lane', length: 187, cover: 'from-amber-300 to-rose-600', bg: 'bg-rose-950', ink: 'bg-[#ffff00] text-black' },
  { title: 'Night Bus Home', artist: 'Metro Hum', length: 222, cover: 'from-sky-400 to-slate-800', bg: 'bg-sky-950', ink: 'bg-[#0000ff] text-white' },
]

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Each theme's colors, and its bar's sizes in pixels at 480 px of height
// (get() scales them with everything else).
const THEMES = {
  color: {
    page: (track) => `${track.bg} text-white`,
    dim: 'text-white/60',
    cover: (track) => `bg-gradient-to-br ${track.cover}`,
    disc: 'text-white/70',
    artist: 'text-white/70',
    bar: 'bg-white/20',
    played: 'bg-white',
    knob: 'bg-white',
    sizes: { bar: 4, played: 4, knob: 12, knobOut: 4, border: 0 },
    skip: 'active:bg-white/20',
    skipIcon: 'text-white/80',
    play: 'bg-white active:bg-white/60',
    playIcon: 'text-black',
  },
  high: {
    page: () => 'bg-white text-black',
    dim: 'text-black',
    cover: () => 'bg-black',
    disc: 'text-white',
    artist: 'text-black',
    bar: 'bg-white border-black',
    played: 'bg-black',
    knob: 'bg-black',
    sizes: { bar: 12, played: 8, knob: 16, knobOut: 8, border: 2 },
    skip: '',
    skipIcon: 'text-black',
    play: 'bg-black',
    playIcon: 'text-white',
  },
  // Colour e-paper: black, no see-through whites or gradients (its six inks
  // make noise of them), the cover one solid ink, the bar outlined in white.
  ink: {
    page: () => 'bg-black text-white',
    dim: 'text-white',
    cover: (track) => track.ink,
    disc: '',
    artist: 'text-white',
    bar: 'bg-black border-white',
    played: 'bg-white',
    knob: 'bg-white',
    sizes: { bar: 12, played: 8, knob: 16, knobOut: 8, border: 2 },
    skip: '',
    skipIcon: 'text-white',
    play: 'bg-white',
    playIcon: 'text-black',
  },
}
const themeOf = (app) => (highContrast(app) ? THEMES.high : app.frame.paper === true ? THEMES.ink : THEMES.color)

let index = 0
let playing = true
let offset = 74 // seconds played when the clock started
let since = null
let clockAt = () => Date.now()

// The player outlives the render: a board may start each render with a fresh
// module, and a frame rendered on its server does, at every tap.
const recallPlayer = () => {
  const kept = frameos.recall('player')
  if (!kept) return
  index = kept.index
  playing = kept.playing
  offset = kept.offset
  since = kept.since
}
const rememberPlayer = () => frameos.remember('player', { index, playing, offset, since })

// Where the bar is, in seconds, and whether it plays. They are signals: play,
// pause and a seek run only the <Seek /> bar and the <PlayButton /> that read
// them, not get(). A skip changes the whole page, so it sets none.
const shownAt = signal(0)
const shownPlaying = signal(true)
const show = () => {
  shownAt.value = position()
  shownPlaying.value = playing
}

const position = () => {
  const t = offset + (playing ? (clockAt() - since) / 1000 : 0)
  return t % tracks[index].length
}
const toggle = () => {
  offset = position(); since = clockAt(); playing = !playing
  rememberPlayer()
  show()
}
const skip = (by) => {
  index = (index + by + tracks.length) % tracks.length; offset = 0; since = clockAt()
  rememberPlayer()
}
// The seek bar's width: the UI's less the page's padding on both sides, set by
// each render for the handlers that run before the next.
let barW = 480 - 64
const seek = (e) => {
  // e.width: the bar's own (2026.10.22+); barW on an older frame.
  const fraction = Math.max(0, Math.min(1, e.localX / (e.width ?? barW)))
  offset = fraction * tracks[index].length; since = clockAt()
  rememberPlayer()
  show()
}
// The keys (a frame's buttons, Tab and Enter) press the bar too: each press
// is a tenth of the track further, the end back to the start. A finger's tap
// seeked already, where it landed.
const seekByKey = (e) => {
  if (!e?.key) return
  const length = tracks[index].length
  const next = Math.floor((position() / length) * 10 + 1e-6) + 1
  offset = next >= 10 ? 0 : (next / 10) * length; since = clockAt()
  rememberPlayer()
  show()
}
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`

const Icon = ({ d, className }) => (
  <svg className={className} viewBox="0 0 24 24"><path fill="currentColor" d={d} /></svg>
)

// Sizes laid out for 480 px of height, scaled by k; text never under what
// reads on a small panel (`least`).
const scaled = (k) => (n, least = 1) => `${Math.max(least, Math.round(n * k))}px`

// The seek bar and the time under it.
const Seek = memo(({ k, w, border, length, t }) => {
  const px = scaled(k)
  const at = shownAt.value
  const played = Math.max(2, Math.round((at * (w - 2 * border)) / length))
  return (
    <div className={`flex flex-col w-full gap-[${px(4)}]`}>
      {/* A mouse passing over the bar sends moves too: seek only while pressed. */}
      <div className={`flex items-center h-[${px(32)}]`} onPointerDown={seek} onPointerMove={(e) => { if (e.buttons) seek(e) }} onClick={seekByKey}>
        <div className={`flex-1 rounded-full h-[${px(t.sizes.bar)}] ${t.bar}${border ? ` border-[${border}px]` : ''}`}>
          <div className={`flex items-center justify-end rounded-full h-[${px(t.sizes.played)}] w-[${played}px] ${t.played}`}>
            <div className={`rounded-full w-[${px(t.sizes.knob)}] h-[${px(t.sizes.knob)}] -mr-[${px(t.sizes.knobOut)}] ${t.knob}`} />
          </div>
        </div>
      </div>
      <div className={`flex justify-between text-[${px(14, 10)}] ${t.dim}`}>
        <span>{clock(at)}</span>
        <span>{clock(length)}</span>
      </div>
    </div>
  )
})

const PlayButton = memo(({ k, t }) => {
  const px = scaled(k)
  return (
    <div className={`w-[${px(80)}] h-[${px(80)}] rounded-full flex items-center justify-center ${t.play}`} onClick={toggle}>
      <Icon className={`w-[${px(40)}] h-[${px(40)}] ${t.playIcon}`} d={shownPlaying.value ? 'M6 4h4v16H6zM14 4h4v16h-4z' : 'M7 4v16l13-8z'} />
    </div>
  )
})

// The size the UI is laid out at: the image it draws into, else the frame
// as the scene sees it (app.frame is the panel's, before the turn).
const uiSize = (app, context) => {
  const turned = [90, 270].includes(app.frame.rotate)
  return [context?.imageWidth ?? (turned ? app.frame.height : app.frame.width),
    context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)]
}

// On a round panel: the cover is a disc in the middle, the time a ring along
// the rim that a finger drags around to seek, the buttons in the arc below.
const RING = { color: { track: 'rgba(255,255,255,0.2)', played: '#ffffff' }, high: { track: '#d4d4d4', played: '#000000' } }
// Where the ring is, set by each round render for the handlers after it.
let ring = { c: 240, r: 220, band: 40 }
let ringHeld = false
const ringSeek = (e, down) => {
  const dx = e.localX - ring.c, dy = e.localY - ring.c
  if (down) ringHeld = Math.abs(Math.hypot(dx, dy) - ring.r) <= ring.band
  if (!ringHeld || (!down && !e.buttons)) return false
  let f = Math.atan2(dx, -dy) / (2 * Math.PI)
  if (f < 0) f += 1
  offset = f * tracks[index].length; since = clockAt()
  rememberPlayer()
  show()
}
const ringPoint = (c, r, f) => [c + r * Math.sin(f * 2 * Math.PI), c - r * Math.cos(f * 2 * Math.PI)]
const RoundSeek = memo(({ size, r, stroke, knob, colors, length, text, dim }) => {
  const at = shownAt.value
  const c = size / 2
  const f = Math.min(0.9999, Math.max(0.0005, at / length))
  const [x0, y0] = ringPoint(c, r, 0)
  const [x1, y1] = ringPoint(c, r, f)
  return (
    <div className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`}>
      <svg className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`} viewBox={`0 0 ${size} ${size}`}>
        <circle cx={c} cy={c} r={r} stroke={colors.track} strokeWidth={stroke} fill="none" />
        <path d={`M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 ${f > 0.5 ? 1 : 0} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}`}
          stroke={colors.played} strokeWidth={stroke} strokeLinecap="round" fill="none" />
        <circle cx={x1.toFixed(1)} cy={y1.toFixed(1)} r={knob} fill={colors.played} />
      </svg>
      <div className={`absolute left-0 top-[${Math.round(c + r * 0.87 - text)}px] w-[${size}px] h-[${text * 2}px] flex items-center justify-center text-[${text}px] ${dim}`}>
        {`${clock(at)} / ${clock(length)}`}
      </div>
    </div>
  )
})

const getRound = (app, context, t) => {
  const W = context.imageWidth, H = context.imageHeight
  const size = Math.min(W, H), r = size / 2
  const k = r / 240
  const n = (v) => Math.max(1, Math.round(v * k))
  const text = (v) => Math.max(14, n(v))
  const stroke = t === THEMES.high ? n(10) : n(6)
  const ringR = r - Math.max(12, n(14)) - n(8)
  ring = { c: r, r: ringR, band: n(36) }
  const track = tracks[index]
  const disc = n(176)
  const box = (cy, h, w, extra = '') => `absolute left-[${Math.round((size - w) / 2)}px] top-[${Math.round(r + cy - h / 2)}px] w-[${Math.round(w)}px] h-[${Math.round(h)}px] flex items-center justify-center ${extra}`
  // The disc turns as the track plays: a light on its grooves shows it.
  const turn = (shownAt.peek() * 0.09) % 1
  const dc = disc / 2
  const [sx, sy] = ringPoint(dc, dc * 0.78, turn)
  const [ex, ey] = ringPoint(dc, dc * 0.78, turn + 0.12)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page(track)}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <div className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`}
          onPointerDown={(e) => ringSeek(e, true)} onPointerMove={(e) => ringSeek(e, false)} />
        <RoundSeek size={size} r={ringR} stroke={stroke} knob={n(9)} colors={t === THEMES.high ? RING.high : RING.color}
          length={track.length} text={text(13)} dim={t.dim} />
        <div className={box(-r * 0.33, disc, disc, `rounded-full ${t.cover(track)}`)}>
          <svg className={`w-[${disc}px] h-[${disc}px] ${t.disc}`} viewBox={`0 0 ${disc} ${disc}`} fill="none" stroke="currentColor" strokeLinecap="round">
            {[0.92, 0.8, 0.68, 0.56].map((g) => <circle cx={dc} cy={dc} r={(dc * g).toFixed(1)} strokeWidth={1} opacity={0.35} />)}
            <path d={`M ${sx.toFixed(1)} ${sy.toFixed(1)} A ${(dc * 0.78).toFixed(1)} ${(dc * 0.78).toFixed(1)} 0 0 1 ${ex.toFixed(1)} ${ey.toFixed(1)}`} strokeWidth={n(4)} opacity={0.8} />
            <circle cx={dc} cy={dc} r={(dc * 0.3).toFixed(1)} strokeWidth={n(3)} />
            <circle cx={dc} cy={dc} r={(dc * 0.08).toFixed(1)} fill="currentColor" />
          </svg>
        </div>
        <div className={box(r * 0.15, n(34), r * 1.5)}>
          <span className={`text-[${text(24)}px] font-bold truncate`}>{track.title}</span>
        </div>
        <div className={box(r * 0.28, n(24), r * 1.4)}>
          <span className={`text-[${text(16)}px] truncate ${t.artist}`}>{`${track.artist} · ${index + 1} of ${tracks.length}`}</span>
        </div>
        <div className={box(r * 0.54, n(80), r * 1.1)}>
          <div className="flex items-center justify-between w-full">
            <div className={`w-[${n(60)}px] h-[${n(60)}px] rounded-full flex items-center justify-center ${t.skip}`} onClick={() => skip(-1)}>
              <Icon className={`w-[${n(34)}px] h-[${n(34)}px] ${t.skipIcon}`} d="M6 6h2v12H6zM9.5 12l8.5 6V6z" />
            </div>
            <PlayButton k={k * 0.95} t={t} />
            <div className={`w-[${n(60)}px] h-[${n(60)}px] rounded-full flex items-center justify-center ${t.skip}`} onClick={() => skip(1)}>
              <Icon className={`w-[${n(34)}px] h-[${n(34)}px] ${t.skipIcon}`} d="M16 6h2v12h-2zM6 18l8.5-6L6 6z" />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export function get(app, context) {
  const t = themeOf(app)
  const round = context?.round === true
  const [width, height] = uiSize(app, context)
  // A short screen wider than tall (a 5.79" strip, a 4.2" e-paper, a 2.8"
  // LCD): the cover on the left, the rest beside it, laid out for 300 px of
  // height. Elsewhere laid out for 480 px of height, then scaled to the
  // height there is, as far as the width allows; what height is left spreads
  // out evenly around it.
  const side = !round && height < 360 && width >= height * 1.25
  const k = side ? Math.max(0.5, Math.min(height / 300, 1)) : Math.max(0.5, Math.min(height / 480, width / 380))
  const px = scaled(k)
  const padX = Math.round((side ? 20 : 32) * k)
  const cover = side ? Math.min(height - 2 * Math.round(20 * k), Math.round(width * 0.4)) : Math.round(168 * k)
  barW = side ? width - 3 * padX - cover : width - 2 * padX
  const border = t.sizes.border ? Math.max(1, Math.round(t.sizes.border * k)) : 0
  if (app.config.at) clockAt = () => Date.parse(app.config.at)
  recallPlayer()
  if (since === null) {
    since = clockAt()
    rememberPlayer()
  }
  const track = tracks[index]
  show()
  if (round) return getRound(app, context, t)
  const label = <span className={`text-[${px(13, 10)}] uppercase font-semibold ${t.dim}`}>{`Track ${index + 1} of ${tracks.length}`}</span>
  const art = (
    <div className={`shrink-0 w-[${cover}px] h-[${cover}px] rounded-[${px(24)}] ${t.cover(track)} flex items-center justify-center`}>
      <svg className={`w-[${Math.round(cover * 0.55)}px] h-[${Math.round(cover * 0.55)}px] ${t.disc}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
        <circle cx={12} cy={12} r={10} />
        <circle cx={12} cy={12} r={6} />
        <circle cx={12} cy={12} r={2} fill="currentColor" />
      </svg>
    </div>
  )
  const names = (
    <div className={`flex flex-col ${side ? 'items-start' : 'items-center'} w-full min-w-0`}>
      <span className={`text-[${px(24, 14)}] font-bold ${side ? 'leading-tight line-clamp-2' : 'truncate'}`}>{track.title}</span>
      <span className={`text-[${px(16, 11)}] truncate ${t.artist}`}>{track.artist}</span>
    </div>
  )
  // Beside the cover the buttons are smaller, to fit the column.
  const skipSize = px(side ? 48 : 64)
  const buttons = (
    <div className={`flex items-center justify-between w-full px-[${px(side ? 0 : 24)}]`}>
      <div className={`w-[${skipSize}] h-[${skipSize}] rounded-full flex items-center justify-center ${t.skip}`} onClick={() => skip(-1)}>
        <Icon className={`w-[${px(36)}] h-[${px(36)}] ${t.skipIcon}`} d="M6 6h2v12H6zM9.5 12l8.5 6V6z" />
      </div>
      <PlayButton k={side ? k * 0.8 : k} t={t} />
      <div className={`w-[${skipSize}] h-[${skipSize}] rounded-full flex items-center justify-center ${t.skip}`} onClick={() => skip(1)}>
        <Icon className={`w-[${px(36)}] h-[${px(36)}] ${t.skipIcon}`} d="M16 6h2v12h-2zM6 18l8.5-6L6 6z" />
      </div>
    </div>
  )
  if (side)
    return (
      <div className={`flex flex-row items-center gap-[${padX}px] px-[${padX}px] ${t.page(track)}`}>
        {art}
        <div className={`flex-1 min-w-0 h-full flex flex-col justify-evenly py-[${px(12)}]`}>
          {label}
          {names}
          <Seek k={k} w={barW} border={border} length={track.length} t={t} />
          {buttons}
        </div>
      </div>
    )
  return (
    <div className={`flex flex-col items-center justify-evenly gap-[${px(14)}] px-[${padX}px] py-[${px(20)}] ${t.page(track)}`}>
      {label}
      {art}
      {names}
      <Seek k={k} w={barW} border={border} length={track.length} t={t} />
      {buttons}
    </div>
  )
}
